def slidingPuzzle(board):
    start = ''.join(str(x) for row in board for x in row)
    goal = '123450'
    if start == goal:
        return 0
    nbr = [(1, 3), (0, 2, 4), (1, 5), (0, 4), (1, 3, 5), (2, 4)]
    seen = {start}
    frontier = [start]
    steps = 0
    while frontier:
        steps += 1
        nxt = []
        for s in frontier:
            z = s.index('0')
            for j in nbr[z]:
                t = list(s)
                t[z], t[j] = t[j], t[z]
                t = ''.join(t)
                if t not in seen:
                    if t == goal:
                        return steps
                    seen.add(t)
                    nxt.append(t)
        frontier = nxt
    return -1
